-- 56 Haunted Hall: drifts the ghosts and fades them. Each ghost is a
-- `canvas_group`, faded whole with CanvasGroup.set - so a half-there ghost
-- is a pale figure, not a stack of see-through parts. Generated by
-- tools/gen_scenes.py.

script = { tick_rate = 60 }

local nav = require("nav")
local SCENE = "scenes/56-haunted-hall.scene"
local COUNT = 4
local captions = true
local ghosts, lights = {}, {}
local t, summon = 0, 0
local status

function init(entity)
    for i = 1, COUNT do
        local root = Entity.find_by_name("Ghost" .. i)
        if root then
            local x, y = Transform.get_position(root)
            local s = Transform.get_scale(root)
            ghosts[#ghosts + 1] = {
                root = root, x = x, y = y, s = s, phase = i * 1.9, speed = (i % 2 == 0) and -38 or 32,
                arm_f = Entity.find_by_name("Ghost" .. i .. "ArmF"), arm_b = Entity.find_by_name("Ghost" .. i .. "ArmB"),
            }
        end
    end
    for i = 1, 4 do lights[i] = Entity.find_by_name("CandleLight" .. i) end
    status = Entity.find_by_name("Status")
end

local function smooth(v)
    v = math.max(0, math.min(1, v))
    return v * v * (3 - 2 * v)
end

function update(entity, dt)
    nav.tick(SCENE)
    if Input.is_key_just_pressed("Tab") then captions = nav.toggle_ui_captions(captions) end
    if Input.is_key_just_pressed("Space") then summon = 3.0 end
    t = t + dt
    summon = math.max(0, summon - dt)
    local seen = 0
    for _, g in ipairs(ghosts) do
        g.x = g.x + g.speed * dt
        if g.x > 760 then g.x = -760 elseif g.x < -760 then g.x = 760 end
        local bob = math.sin(t * 1.3 + g.phase) * 14
        Transform.set_position(g.root, g.x, g.y + bob)
        Transform.set_scale(g.root, (g.speed > 0 and 1 or -1) * g.s, g.s)
        -- In and out of being: long fades, a while gone between.
        local o = smooth(math.sin(t * 0.45 + g.phase) * 1.6)
        o = math.max(o, smooth(summon))
        CanvasGroup.set(g.root, "opacity", 0.75 * o)
        if o > 0.05 then seen = seen + 1 end
        local wave = math.sin(t * 2.2 + g.phase)
        if g.arm_f then Transform.set_rotation(g.arm_f, 0.35 + 0.25 * wave) end
        if g.arm_b then Transform.set_rotation(g.arm_b, -0.3 - 0.2 * wave) end
    end
    for i, l in ipairs(lights) do
        if l then Lighting.set_intensity(l, 0.85 + 0.12 * math.sin(t * 11 + i * 2.1) + 0.06 * math.sin(t * 23 + i)) end
    end
    if status then UI.set_text(status, seen .. " of " .. #ghosts .. " here") end
end
